solution_code:
function calculate(a: number, b: number, op: string): number {
  if (op === '+') return a + b;
  if (op === '-') return a - b;
  if (op === '*') return a * b;
  if (op === '/' && b !== 0) return Math.trunc(a / b);
  return 0;
}

